export function sniff(head: Uint8Array): string | undefined {
  const part = (p: Part) =>
    p.at + p.bytes.length <= head.length && p.bytes.every((b, i) => (head[p.at + i] & (p.mask?.[i] ?? 0xff)) === b);
  return SIGNATURES.find((s) => s.parts.every(part))?.mime;
}
